// Build-time fallback for the Rust doc-core wasm glue (`media/wasm/doc_wasm.js`).
//
// The real module is generated by `wasm-pack build rust/doc-wasm --target web` into
// `vscode-extension/media/wasm/` (gitignored). On a fresh checkout that hasn't run the wasm
// build, esbuild bundles this stub instead so the webview bundle still builds. The stub makes
// wasm init fail cleanly, which causes the webview to fall back to the TypeScript parser — the
// editor is never broken by a missing wasm artifact.

/** Stand-in for the wasm-bindgen default `init`: always fails so the caller uses the fallback. */
export default async function init() {
  throw new Error('doc-core wasm not built (run `wasm-pack build rust/doc-wasm --target web`).');
}

/** Stand-in for the wasm `parse`. Never reached, because `init` above always fails first. */
export function parse() {
  throw new Error('doc-core wasm not built.');
}
